/* Umbraco block grid layout. The markup comes from Views/Partials/blockgrid/ and
   exposes its column/row spans as CSS custom properties; this turns them into a grid. */
.umb-block-grid__layout-container {
    display: grid;
    grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
    gap: 3rem 2rem;
}
.umb-block-grid__layout-item {
    grid-column: span var(--umb-block-grid--item-column-span, 12);
    grid-row: span var(--umb-block-grid--item-row-span, 1);
    min-width: 0;
}
@media (max-width: 40rem) {
    .umb-block-grid__layout-item {
        grid-column: 1 / -1;
    }
}

/* Rich text block body */
.rich-text {
    font-size: 1.125rem;
    line-height: 1.8;
    color: var(--color-slate-700);
}
.rich-text h2 {
    font-size: 1.75rem;
    line-height: 1.25;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: var(--color-slate-900);
    margin-top: 2.5rem;
    margin-bottom: 1rem;
}
.rich-text h2:first-child {
    margin-top: 0;
}
.rich-text p {
    margin-bottom: 1.25rem;
}
